import java.util.*;

public class Main {
    static class Pair {
        int location;
        int dist;

        Pair(int location, int dist) {
            this.location = location;
            this.dist = dist;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        if (n >= m) {
            System.out.println(n - m);
        } else {
            boolean[] visited = new boolean[m + 2];
            Queue<Pair> queue = new ArrayDeque<>();
            queue.offer(new Pair(n, 0));
            visited[n] = true;

            int ans = 0;
            while (!queue.isEmpty()) {
                Pair tmp = queue.poll();

                if (tmp.location == m) {
                    ans = tmp.dist;
                    break;
                }

                if (tmp.location * 2 <= m + 1 && !visited[tmp.location * 2]) {
                    queue.offer(new Pair(tmp.location * 2, tmp.dist + 1));
                    visited[tmp.location * 2] = true;
                }
                if (tmp.location - 1 >= 0 && !visited[tmp.location - 1]) {
                    queue.offer(new Pair(tmp.location - 1, tmp.dist + 1));
                    visited[tmp.location - 1] = true;
                }
            }
            System.out.println(ans);
        }
    }
}

